/**
 * Target normalisation.
 *
 * Selector strings are passed straight through to GSAP so its scoping (via
 * `useGSAP({ scope })` or `gsap.context()`) keeps working — resolving them to
 * elements here would silently break that and let a selector escape its
 * component.
 */
import type { MotionTarget } from "../types";

function isRef(value: object): value is { current: Element | null } {
  return "current" in value;
}

/**
 * Unwraps React refs; leaves selectors, elements and lists untouched.
 * Returns `null` when there is nothing to animate.
 */
export function resolveTarget(target: MotionTarget): gsap.TweenTarget | null {
  if (target === null || target === undefined) return null;
  if (typeof target === "string") return target;
  if (target instanceof Element) return target;
  if (Array.isArray(target)) return target.length > 0 ? target : null;
  if (isRef(target)) return target.current;
  // NodeList
  return target.length > 0 ? Array.from(target) : null;
}

/**
 * Resolves a target to concrete elements. Use only where real nodes are
 * required (measuring, per-element triggers); prefer `resolveTarget` otherwise.
 */
export function resolveElements(target: MotionTarget): Element[] {
  const resolved = resolveTarget(target);
  if (resolved === null) return [];
  if (typeof resolved === "string") {
    return Array.from(document.querySelectorAll(resolved));
  }
  if (resolved instanceof Element) return [resolved];
  if (Array.isArray(resolved)) {
    return resolved.filter((item): item is Element => item instanceof Element);
  }
  return [];
}
