/**
 * Page transition overlay animations.
 *
 * These build the two halves of a route change: `cover` hides the outgoing
 * page, `reveal` uncovers the incoming one. Both animate transform or opacity
 * on a single fixed element, so a transition never triggers layout.
 */
import type { PageTransitionVariant } from "../types";

import { DURATION, EASING } from "../core/config";
import { ensureRegistered, gsap } from "../core/gsap";

export interface TransitionPhaseOptions {
  variant: PageTransitionVariant;
  duration: number;
  ease: string;
}

/** Resting state: fully out of the way and not catching pointer events. */
export function resetOverlay(
  overlay: Element,
  variant: PageTransitionVariant,
): void {
  ensureRegistered();

  const base = { pointerEvents: "none" as const };

  switch (variant) {
    case "fade":
      gsap.set(overlay, { ...base, autoAlpha: 0 });
      return;
    case "slide":
      gsap.set(overlay, { ...base, autoAlpha: 1, yPercent: 100 });
      return;
    case "curtain":
    default:
      gsap.set(overlay, {
        ...base,
        autoAlpha: 1,
        scaleY: 0,
        transformOrigin: "bottom center",
      });
  }
}

/** Animates the overlay in, hiding the outgoing page. */
export function coverAnimation(
  overlay: Element,
  { variant, duration, ease }: TransitionPhaseOptions,
): gsap.core.Tween {
  ensureRegistered();

  // Block input for the whole transition so a second click cannot start a
  // navigation while the first is still playing.
  gsap.set(overlay, { pointerEvents: "auto" });

  switch (variant) {
    case "fade":
      return gsap.fromTo(
        overlay,
        { autoAlpha: 0 },
        { autoAlpha: 1, duration, ease },
      );
    case "slide":
      return gsap.fromTo(
        overlay,
        { autoAlpha: 1, yPercent: 100 },
        { yPercent: 0, duration, ease },
      );
    case "curtain":
    default:
      return gsap.fromTo(
        overlay,
        { autoAlpha: 1, scaleY: 0, transformOrigin: "bottom center" },
        { scaleY: 1, duration, ease },
      );
  }
}

/** Animates the overlay away, uncovering the incoming page. */
export function revealAnimation(
  overlay: Element,
  { variant, duration, ease }: TransitionPhaseOptions,
): gsap.core.Tween {
  ensureRegistered();

  const onComplete = () => gsap.set(overlay, { pointerEvents: "none" });

  switch (variant) {
    case "fade":
      return gsap.to(overlay, { autoAlpha: 0, duration, ease, onComplete });
    case "slide":
      // Continues in the same direction rather than retreating, so the panel
      // reads as one object passing over the page.
      return gsap.fromTo(
        overlay,
        { yPercent: 0 },
        { yPercent: -100, duration, ease, onComplete },
      );
    case "curtain":
    default:
      return gsap.fromTo(
        overlay,
        { scaleY: 1, transformOrigin: "top center" },
        { scaleY: 0, duration, ease, onComplete },
      );
  }
}

/** House defaults for a route change. */
export const TRANSITION_DEFAULTS = {
  variant: "curtain" as PageTransitionVariant,
  /** Deliberately shorter than `DURATION.reveal` — a transition is a gap in
   *  the experience, and every extra frame is dead time. */
  duration: DURATION.base,
  ease: EASING.dramatic,
} as const;
