/**
 * Parallax.
 *
 * Purely decorative: there is no end state to arrive at, the movement *is* the
 * effect. Under reduced motion it is not created at all.
 */
import type { MotionTarget, ParallaxOptions } from "../types";

import { EASING } from "../core/config";
import { isBrowser } from "../core/env";
import { ensureRegistered, gsap } from "../core/gsap";
import { resolveTarget } from "../core/target";
import {
  shouldSkipDecorativeMotion,
  toScrollTriggerVars,
} from "../core/vars";

/**
 * Moves a target at a different rate than the scroll.
 *
 * Displacement is expressed in percent of the element's own size, so the effect
 * holds at every viewport without media queries.
 *
 * Keep `speed` under ~0.4. Beyond that the element visibly detaches from the
 * layout and the page reads as broken rather than deep.
 *
 * @example
 * ```ts
 * parallax(".hero-bg", { speed: 0.25 });
 * ```
 */
export function parallax(
  target: MotionTarget,
  options: ParallaxOptions = {},
): gsap.core.Tween | null {
  if (!isBrowser) return null;
  if (shouldSkipDecorativeMotion()) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  const { speed = 0.2, axis = "y", scroll } = options;
  const property = axis === "x" ? "xPercent" : "yPercent";
  const travel = speed * 100;

  return gsap.fromTo(
    resolved,
    { [property]: -travel / 2 },
    {
      [property]: travel / 2,
      // Scrubbed animation must be linear or scroll and position desynchronise.
      ease: EASING.none,
      scrollTrigger: toScrollTriggerVars(scroll ?? true, {
        trigger: target,
        start: "top bottom",
        end: "bottom top",
        scrub: true,
      }),
    },
  );
}
