/**
 * Opacity primitives.
 *
 * `autoAlpha` is used rather than `opacity` so a faded-out element also gets
 * `visibility: hidden` and stops intercepting pointer events.
 */
import type { FadeOptions, MotionTarget } from "../types";

import { DURATION, EASING } from "../core/config";
import { isBrowser } from "../core/env";
import { ensureRegistered, gsap } from "../core/gsap";
import { resolveTarget } from "../core/target";
import { resolveTimings, toScrollTriggerVars } from "../core/vars";

/**
 * Fades a target in from transparent.
 *
 * @example
 * ```ts
 * fadeIn(ref, { scroll: true, duration: DURATION.slow });
 * ```
 */
export function fadeIn(
  target: MotionTarget,
  options: FadeOptions = {},
): gsap.core.Tween | null {
  if (!isBrowser) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  const { duration, delay, ease, stagger } = resolveTimings(options, {
    duration: DURATION.base,
    ease: EASING.premium,
  });

  return gsap.fromTo(
    resolved,
    { autoAlpha: options.opacity ?? 0 },
    {
      autoAlpha: 1,
      duration,
      delay,
      ease,
      stagger,
      onStart: options.onStart,
      onComplete: options.onComplete,
      scrollTrigger: toScrollTriggerVars(options.scroll, { trigger: target }),
    },
  );
}

/** Fades a target out. Leaves it `visibility: hidden` when fully transparent. */
export function fadeOut(
  target: MotionTarget,
  options: FadeOptions = {},
): gsap.core.Tween | null {
  if (!isBrowser) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  const { duration, delay, ease, stagger } = resolveTimings(options, {
    duration: DURATION.fast,
    ease: EASING.soft,
  });

  return gsap.to(resolved, {
    autoAlpha: options.opacity ?? 0,
    duration,
    delay,
    ease,
    stagger,
    onStart: options.onStart,
    onComplete: options.onComplete,
    scrollTrigger: toScrollTriggerVars(options.scroll, { trigger: target }),
  });
}
