"use client";

import { useGSAP } from "@gsap/react";
import { useRef, type RefObject } from "react";

import type { ParallaxOptions } from "../types";
import { ensureRegistered } from "../core/gsap";
import { parallax } from "../animations/parallax";

/**
 * Attaches parallax to an element and returns the ref to spread onto it.
 *
 * @example
 * ```tsx
 * const backdrop = useParallax<HTMLDivElement>({ speed: 0.25 });
 * return <div ref={backdrop} className="backdrop" />;
 * ```
 */
export function useParallax<T extends Element = HTMLDivElement>(
  options: ParallaxOptions = {},
): RefObject<T | null> {
  const ref = useRef<T | null>(null);
  ensureRegistered();

  const { speed, axis } = options;

  useGSAP(
    () => {
      if (!ref.current) return;
      parallax(ref.current, options);
    },
    // Options is typically an inline literal, so depend on the values that
    // actually change the animation rather than object identity.
    { dependencies: [speed, axis] },
  );

  return ref;
}
