/**
 * Scroll progress observation.
 *
 * Progress is delivered through a callback rather than React state on purpose:
 * a scroll handler that calls `setState` re-renders the tree on every frame.
 * Drive a ref, a CSS variable, or a GSAP quickSetter from these instead.
 */
import type { MotionTarget, ScrollOptions } from "../types";

import { ScrollTrigger, ensureRegistered } from "../core/gsap";
import { isBrowser } from "../core/env";
import { toScrollTriggerVars } from "../core/vars";

/**
 * Reports 0→1 progress as `target` moves through the scroll range.
 * Returns an unsubscribe function.
 */
export function watchScrollProgress(
  target: MotionTarget,
  onProgress: (progress: number, direction: 1 | -1) => void,
  options: Omit<ScrollOptions, "trigger" | "onUpdate"> = {},
): () => void {
  if (!isBrowser) return () => {};
  ensureRegistered();

  const vars = toScrollTriggerVars(
    { ...options, trigger: target, onUpdate: onProgress },
    { start: "top bottom", end: "bottom top" },
  );
  if (!vars) return () => {};

  // Progress must track scroll continuously, not just at the boundaries.
  vars.scrub = true;

  const instance = ScrollTrigger.create(vars);
  return () => instance.kill();
}

/** Current page scroll progress, 0→1. Returns 0 on the server. */
export function getPageScrollProgress(): number {
  if (!isBrowser) return 0;
  const scrollable =
    document.documentElement.scrollHeight - window.innerHeight;
  if (scrollable <= 0) return 0;
  return Math.min(1, Math.max(0, window.scrollY / scrollable));
}

/**
 * Reports overall page scroll progress, 0→1.
 * Returns an unsubscribe function.
 */
export function watchPageScrollProgress(
  onProgress: (progress: number) => void,
): () => void {
  if (!isBrowser) return () => {};
  ensureRegistered();

  const instance = ScrollTrigger.create({
    start: 0,
    end: "max",
    scrub: true,
    onUpdate: (self) => onProgress(self.progress),
  });

  return () => instance.kill();
}
