"use client";

import type { LenisOptions } from "lenis";
import "lenis/dist/lenis.css";
import Lenis from "lenis";
import {
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";

import { prefersReducedMotion, subscribeToReducedMotion } from "../core/env";
import { getMotionConfig } from "../core/config";
import { ensureRegistered } from "../core/gsap";
import {
  connectScrollTrigger,
  createSmoothScroll,
  setActiveLenis,
} from "../core/lenis";
import { LenisContext } from "../hooks/useLenis";

export interface SmoothScrollProviderProps {
  children: ReactNode;
  /**
   * Lenis overrides merged over the house defaults.
   * Read once, on mount — later changes are ignored.
   */
  options?: LenisOptions;
  /**
   * Skip Lenis entirely and use native scrolling. Useful for admin routes or
   * embedded views where smooth scroll fights the host page.
   */
  disabled?: boolean;
}

/**
 * Owns the single Lenis instance for the application and keeps it on the same
 * clock as GSAP and ScrollTrigger.
 *
 * Mount once, inside the root layout's `<body>`. Every page below it gets
 * smooth scroll with no further setup.
 *
 * @example
 * ```tsx
 * export default function RootLayout({ children }) {
 *   return (
 *     <html lang="en">
 *       <body>
 *         <SmoothScrollProvider>{children}</SmoothScrollProvider>
 *       </body>
 *     </html>
 *   );
 * }
 * ```
 */
export function SmoothScrollProvider({
  children,
  options,
  disabled = false,
}: SmoothScrollProviderProps) {
  const [lenis, setLenis] = useState<Lenis | null>(null);

  // Captured on mount: an inline object literal from the caller would otherwise
  // tear down and rebuild Lenis on every render.
  const optionsRef = useRef(options);

  // Subscribed rather than read once, so toggling the OS setting mid-visit
  // takes effect without a reload. Reports false during SSR, which matches the
  // server-rendered markup and avoids a hydration mismatch.
  const reducedMotion = useSyncExternalStore(
    subscribeToReducedMotion,
    prefersReducedMotion,
    () => false,
  );

  useEffect(() => {
    ensureRegistered();

    // Under reduced motion, leave native scrolling alone. ScrollTrigger keeps
    // working — it just reads native scroll position instead of Lenis.
    const suppressed =
      disabled || (getMotionConfig().respectReducedMotion && reducedMotion);
    if (suppressed) return;

    const instance = createSmoothScroll(optionsRef.current);
    if (!instance) return;

    const disconnect = connectScrollTrigger(instance);
    setActiveLenis(instance);
    setLenis(instance);

    return () => {
      disconnect();
      instance.destroy();
      setActiveLenis(null);
      setLenis(null);
    };
  }, [reducedMotion, disabled]);

  return (
    <LenisContext.Provider value={lenis}>{children}</LenisContext.Provider>
  );
}

export default SmoothScrollProvider;
