"use client";

import type Lenis from "lenis";
import { createContext, useCallback, useContext, useEffect } from "react";

import { type ScrollToOptions, scrollTo } from "../core/lenis";

/**
 * Holds the active Lenis instance.
 *
 * `null` is a legitimate value, not an error: it means smooth scrolling is
 * intentionally off — the visitor prefers reduced motion, or no provider is
 * mounted. Consumers must handle it rather than assume an instance.
 */
export const LenisContext = createContext<Lenis | null>(null);

/** The active Lenis instance, or `null` when smooth scrolling is off. */
export function useLenis(): Lenis | null {
  return useContext(LenisContext);
}

/**
 * Subscribes to Lenis scroll events for the lifetime of the component.
 *
 * The callback fires every frame while scrolling, so it must not call
 * `setState`. Write to a ref or drive a GSAP setter instead.
 *
 * Wrap the callback in `useCallback`, or it re-subscribes on every render.
 */
export function useLenisScroll(callback: (lenis: Lenis) => void): void {
  const lenis = useLenis();

  useEffect(() => {
    if (!lenis) return;
    lenis.on("scroll", callback);
    return () => lenis.off("scroll", callback);
  }, [lenis, callback]);
}

/**
 * Returns a stable scroll-to function for nav links and back-to-top buttons.
 *
 * Falls back to native scrolling when Lenis is off, so anchors keep working
 * under reduced motion.
 *
 * @example
 * ```tsx
 * const scrollTo = useScrollTo();
 * <button onClick={() => scrollTo("#contact", { offset: -80 })}>Contact</button>
 * ```
 */
export function useScrollTo(): (
  target: string | Element | number,
  options?: ScrollToOptions,
) => void {
  return useCallback(
    (target: string | Element | number, options?: ScrollToOptions) => {
      scrollTo(target, options);
    },
    [],
  );
}
