"use client";

import { usePathname, useRouter } from "next/navigation";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";

import type { PageTransitionVariant } from "../types";

import { getMotionConfig } from "../core/config";
import { prefersReducedMotion, subscribeToReducedMotion } from "../core/env";
import { ScrollTrigger, ensureRegistered } from "../core/gsap";
import { getLenis } from "../core/lenis";
import {
  TRANSITION_DEFAULTS,
  coverAnimation,
  resetOverlay,
  revealAnimation,
} from "../animations/transition";
import {
  TransitionRouterContext,
  type TransitionRouter,
} from "../hooks/useTransitionRouter";

/**
 * The App Router unmounts the outgoing page the instant navigation commits, so
 * there is no window in which to animate it out. The overlay exists to create
 * that window: cover the viewport, navigate behind it, then uncover.
 */
type Phase = "idle" | "covering" | "navigating" | "revealing";

export interface PageTransitionProviderProps {
  children: ReactNode;
  /** Overlay style. Default `"curtain"`. */
  variant?: PageTransitionVariant;
  /** Overlay colour. Should match the site background or a brand tone. */
  color?: string;
  /** Seconds per half of the transition. Default `DURATION.base`. */
  duration?: number;
  /** Easing. Default `EASING.dramatic`. */
  ease?: string;
  /** Optional content rendered inside the overlay, e.g. a logo mark. */
  overlayContent?: ReactNode;
  /** Skip transitions entirely and navigate immediately. */
  disabled?: boolean;
}

/** Inline resting state, so the overlay is never visible before hydration. */
function restingStyle(variant: PageTransitionVariant): CSSProperties {
  switch (variant) {
    case "fade":
      return { opacity: 0, visibility: "hidden" };
    case "slide":
      return { transform: "translateY(100%)" };
    case "curtain":
    default:
      return { transform: "scaleY(0)", transformOrigin: "bottom center" };
  }
}

/**
 * Cinematic route transitions.
 *
 * Mount inside `SmoothScrollProvider`, in the root layout. Navigate with
 * {@link useTransitionRouter} or `TransitionLink` — a plain `next/link`
 * bypasses the transition and navigates instantly.
 *
 * Under reduced motion the overlay never animates; navigation is immediate.
 *
 * @example
 * ```tsx
 * <SmoothScrollProvider>
 *   <PageTransitionProvider variant="curtain" color="#0a0a0a">
 *     {children}
 *   </PageTransitionProvider>
 * </SmoothScrollProvider>
 * ```
 */
export function PageTransitionProvider({
  children,
  variant = TRANSITION_DEFAULTS.variant,
  color = "#0a0a0a",
  duration = TRANSITION_DEFAULTS.duration,
  ease = TRANSITION_DEFAULTS.ease,
  overlayContent,
  disabled = false,
}: PageTransitionProviderProps) {
  const router = useRouter();
  const pathname = usePathname();

  const overlayRef = useRef<HTMLDivElement>(null);
  const phase = useRef<Phase>("idle");
  const [isTransitioning, setIsTransitioning] = useState(false);

  const suppressed = useCallback(() => {
    if (disabled) return true;
    return getMotionConfig().respectReducedMotion && prefersReducedMotion();
  }, [disabled]);

  // Re-render on OS setting changes so `suppressed()` is re-evaluated.
  const [, force] = useState(0);
  useEffect(() => subscribeToReducedMotion(() => force((n) => n + 1)), []);

  const navigate = useCallback(
    (href: string, mode: "push" | "replace") => {
      const go = () =>
        mode === "push" ? router.push(href) : router.replace(href);

      if (suppressed() || !overlayRef.current) {
        go();
        return;
      }
      // Ignore clicks fired while a transition is already playing.
      if (phase.current !== "idle") return;

      ensureRegistered();
      phase.current = "covering";
      setIsTransitioning(true);

      coverAnimation(overlayRef.current, { variant, duration, ease }).eventCallback(
        "onComplete",
        () => {
          phase.current = "navigating";
          go();
        },
      );
    },
    [router, suppressed, variant, duration, ease],
  );

  // Fires once the new route has committed and its DOM is mounted.
  useEffect(() => {
    if (phase.current !== "navigating") return;
    const overlay = overlayRef.current;
    if (!overlay) return;

    phase.current = "revealing";

    // Next resets native scroll, but Lenis keeps its own position and would
    // animate the new page back down from the old offset.
    getLenis()?.scrollTo(0, { immediate: true });

    // Two frames: one for the new page to mount, one for it to lay out. Trigger
    // positions measured before that are wrong.
    const frame = requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        ScrollTrigger.refresh();
        revealAnimation(overlay, { variant, duration, ease }).eventCallback(
          "onComplete",
          () => {
            resetOverlay(overlay, variant);
            phase.current = "idle";
            setIsTransitioning(false);
          },
        );
      });
    });

    return () => cancelAnimationFrame(frame);
  }, [pathname, variant, duration, ease]);

  const value = useMemo<TransitionRouter>(
    () => ({
      push: (href) => navigate(href, "push"),
      replace: (href) => navigate(href, "replace"),
      // Browser history restores scroll position itself; covering it would
      // fight that and land the user in the wrong place.
      back: () => router.back(),
      isTransitioning,
    }),
    [navigate, router, isTransitioning],
  );

  return (
    <TransitionRouterContext.Provider value={value}>
      {children}
      <div
        ref={overlayRef}
        aria-hidden="true"
        style={{
          position: "fixed",
          inset: 0,
          zIndex: 9999,
          background: color,
          pointerEvents: "none",
          display: "grid",
          placeItems: "center",
          willChange: "transform, opacity",
          ...restingStyle(variant),
        }}
      >
        {overlayContent}
      </div>
    </TransitionRouterContext.Provider>
  );
}

export default PageTransitionProvider;
