/**
 * Lenis lifecycle and the Lenis <-> ScrollTrigger bridge.
 *
 * Lenis scrolls the real window, so ScrollTrigger needs no `scrollerProxy`.
 * What it does need is to be told when Lenis moved, and Lenis needs to be
 * driven from GSAP's ticker — otherwise the two run on separate rAF loops and
 * every scroll-linked animation trails the scroll position by a frame.
 */
import Lenis, { type LenisOptions } from "lenis";

import { isBrowser } from "./env";
import { ScrollTrigger, ensureRegistered, gsap } from "./gsap";

/** GSAP's stock lag smoothing, restored when the bridge is torn down. */
const DEFAULT_LAG_SMOOTHING: [number, number] = [500, 33];

/**
 * House scroll feel. Tuned once here rather than per project so every
 * LeadStrikes site scrolls with the same weight.
 */
export const DEFAULT_LENIS_OPTIONS: LenisOptions = {
  duration: 1.2,
  easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
  smoothWheel: true,
  // Touch devices already have momentum scrolling. Overriding it reads as lag.
  syncTouch: false,
  // GSAP's ticker drives the loop instead — see connectScrollTrigger().
  autoRaf: false,
};

let activeLenis: Lenis | null = null;

/**
 * Creates a Lenis instance using the house defaults.
 * Returns `null` on the server.
 */
export function createSmoothScroll(options: LenisOptions = {}): Lenis | null {
  if (!isBrowser) return null;
  ensureRegistered();
  return new Lenis({ ...DEFAULT_LENIS_OPTIONS, ...options });
}

/**
 * Puts Lenis and ScrollTrigger on one clock.
 * Returns a teardown that fully unwinds the connection.
 */
export function connectScrollTrigger(lenis: Lenis): () => void {
  ensureRegistered();

  const onScroll = () => ScrollTrigger.update();
  lenis.on("scroll", onScroll);

  // GSAP's ticker reports seconds; Lenis expects milliseconds.
  const raf = (time: number) => lenis.raf(time * 1000);
  gsap.ticker.add(raf);

  // Lag smoothing lets GSAP fast-forward after a dropped frame, which would
  // make scroll position jump ahead of the wheel.
  gsap.ticker.lagSmoothing(0);

  ScrollTrigger.refresh();

  return () => {
    lenis.off("scroll", onScroll);
    gsap.ticker.remove(raf);
    gsap.ticker.lagSmoothing(...DEFAULT_LAG_SMOOTHING);
  };
}

/**
 * Records the app-wide instance so non-React helpers (`scrollTo`) can reach it.
 * Called by SmoothScrollProvider; not part of the public surface.
 */
export function setActiveLenis(lenis: Lenis | null): void {
  activeLenis = lenis;
}

/**
 * The active Lenis instance, or `null` when smooth scrolling is off — either
 * because no provider is mounted or the visitor prefers reduced motion.
 */
export function getLenis(): Lenis | null {
  return activeLenis;
}

/** Options accepted by {@link scrollTo}. */
export interface ScrollToOptions {
  /** Pixels to offset the final position by. Negative scrolls further up. */
  offset?: number;
  /** Seconds. Defaults to the instance's configured duration. */
  duration?: number;
  /** Jump with no animation. */
  immediate?: boolean;
  onComplete?: () => void;
}

/**
 * Scrolls to an element, selector, or absolute offset.
 *
 * Falls back to native scrolling when Lenis is not active, so anchor navigation
 * keeps working under reduced motion.
 */
export function scrollTo(
  target: string | Element | number,
  options: ScrollToOptions = {},
): void {
  if (!isBrowser) return;

  const lenis = getLenis();
  if (lenis) {
    // Lenis types the element case as HTMLElement; any Element works at
    // runtime, and narrowing the public API would reject SVG targets.
    lenis.scrollTo(target as string | number | HTMLElement, {
      offset: options.offset ?? 0,
      duration: options.duration,
      immediate: options.immediate,
      onComplete: options.onComplete,
    });
    return;
  }

  const offset = options.offset ?? 0;
  let top: number;

  if (typeof target === "number") {
    top = target + offset;
  } else {
    const element =
      typeof target === "string" ? document.querySelector(target) : target;
    if (!element) return;
    top = element.getBoundingClientRect().top + window.scrollY + offset;
  }

  window.scrollTo({
    top,
    behavior: options.immediate ? "auto" : "smooth",
  });
  options.onComplete?.();
}

export type { Lenis, LenisOptions };
