/**
 * Single point of GSAP plugin registration.
 *
 * Registration is lazy and idempotent: every public entry point in the engine
 * calls `ensureRegistered()` first, so consumers never have to remember to
 * register anything, and `sideEffects: false` stays honest for tree-shaking.
 */
import { useGSAP } from "@gsap/react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { SplitText } from "gsap/SplitText";

import { getMotionConfig } from "./config";
import { isBrowser } from "./env";

let registered = false;

/**
 * Registers plugins and applies global defaults.
 * Idempotent, and a no-op on the server.
 */
export function ensureRegistered(): void {
  if (registered || !isBrowser) return;
  registered = true;

  gsap.registerPlugin(useGSAP, ScrollTrigger, SplitText);

  const { defaultDuration, defaultEase } = getMotionConfig();
  gsap.defaults({ duration: defaultDuration, ease: defaultEase });

  gsap.config({
    // "auto" GPU-promotes only while a tween runs, so long-lived compositing
    // layers don't leave text blurry after it settles.
    force3D: "auto",
    nullTargetWarn: process.env.NODE_ENV !== "production",
  });

  ScrollTrigger.config({
    // Mobile browsers fire resize when the URL bar hides. Refreshing there
    // makes pinned sections jump mid-scroll.
    ignoreMobileResize: true,
  });
}

/** True once plugins have been registered. */
export function isRegistered(): boolean {
  return registered;
}

export { gsap, ScrollTrigger, SplitText, useGSAP };
