/**
 * Section pinning — the backbone of scroll-driven storytelling.
 */
import type { MotionTarget, PinOptions } from "../types";

import { isBrowser } from "../core/env";
import { ScrollTrigger, ensureRegistered } from "../core/gsap";
import { resolveTarget } from "../core/target";
import { isMotionSuppressed, toScrollTriggerVars } from "../core/vars";

/**
 * Holds a section fixed while the page scrolls past it, optionally scrubbing a
 * timeline across the pinned range.
 *
 * Never animate the pinned element itself — GSAP owns its transform while it is
 * pinned. Animate its children.
 *
 * Pinning is skipped under reduced motion: a section that traps the scroll is a
 * usability problem, not a decoration.
 *
 * @example
 * ```ts
 * const tl = gsap.timeline()
 *   .to(".panel-1", { autoAlpha: 0, ease: EASING.none })
 *   .to(".panel-2", { autoAlpha: 1, ease: EASING.none });
 *
 * pinSection(sectionRef, { animation: tl, end: "+=200%", scrub: 1 });
 * ```
 */
export function pinSection(
  target: MotionTarget,
  options: PinOptions = {},
): ScrollTrigger | null {
  if (!isBrowser) return null;
  if (isMotionSuppressed()) return null;
  ensureRegistered();

  const trigger = resolveTarget(target);
  if (!trigger) return null;

  const vars = toScrollTriggerVars(
    {
      trigger: target,
      start: options.start ?? "top top",
      end: options.end ?? "+=100%",
      pin: options.pin ?? true,
      pinSpacing: options.pinSpacing ?? true,
      scrub: options.scrub ?? true,
      markers: options.markers,
      id: options.id,
      ...(options.onProgress
        ? { onUpdate: (progress: number) => options.onProgress?.(progress) }
        : {}),
    },
    {},
  );
  if (!vars) return null;

  if (options.animation) vars.animation = options.animation;

  return ScrollTrigger.create(vars);
}
