"use client";

import Link from "next/link";
import type { ComponentProps, MouseEvent } from "react";

import { useTransitionRouter } from "../hooks/useTransitionRouter";

export interface TransitionLinkProps extends ComponentProps<typeof Link> {
  /** Navigate immediately, skipping the transition. */
  instant?: boolean;
}

/**
 * Drop-in `next/link` replacement that plays the page transition.
 *
 * Renders a real anchor, so prefetching, middle-click, ctrl-click and "open in
 * new tab" all behave normally — only a plain left click is intercepted.
 *
 * @example
 * ```tsx
 * <TransitionLink href="/work">Work</TransitionLink>
 * ```
 */
export function TransitionLink({
  instant = false,
  onClick,
  href,
  ...props
}: TransitionLinkProps) {
  const router = useTransitionRouter();

  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (instant || event.defaultPrevented) return;

    // Let the browser handle anything that is not a plain left click.
    if (
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey ||
      props.target === "_blank"
    ) {
      return;
    }

    const url = typeof href === "string" ? href : href.toString();

    // External and protocol links are the browser's job.
    if (/^([a-z]+:)?\/\//i.test(url) || url.startsWith("mailto:")) return;

    event.preventDefault();
    router.push(url);
  };

  return <Link href={href} onClick={handleClick} {...props} />;
}

export default TransitionLink;
