/**
 * Batched reveals.
 *
 * One ScrollTrigger per card in a 40-card grid is 40 sets of start/end
 * calculations on every refresh. `ScrollTrigger.batch()` groups the elements
 * that cross the threshold in the same frame and animates them together, which
 * is both cheaper and the only way to get a correct stagger across a grid.
 */
import type { MotionTarget, RevealOptions } from "../types";

import { DISTANCE, DURATION, EASING, STAGGER } from "../core/config";
import { isBrowser } from "../core/env";
import { ScrollTrigger, ensureRegistered, gsap } from "../core/gsap";
import { resolveElements } from "../core/target";
import { isMotionSuppressed } from "../core/vars";

export interface BatchRevealOptions extends RevealOptions {
  /** Max elements per batch. Default 8. */
  batchMax?: number;
  /** Seconds to collect a batch. Default one frame. */
  interval?: number;
  /** Reverse the reveal when scrolling back up. Default `false`. */
  reverse?: boolean;
  /** ScrollTrigger start. Default `"top 85%"`. */
  start?: string;
}

/**
 * Reveals many elements as they enter the viewport, staggered per batch.
 *
 * @example
 * ```ts
 * batchReveal(".card", { direction: "up", stagger: STAGGER.base });
 * ```
 */
export function batchReveal(
  targets: MotionTarget,
  options: BatchRevealOptions = {},
): ScrollTrigger[] {
  if (!isBrowser) return [];
  ensureRegistered();

  const elements = resolveElements(targets);
  if (elements.length === 0) return [];

  const {
    direction = "up",
    distance = DISTANCE.md,
    from = 0,
    duration = DURATION.base,
    ease = EASING.premium,
    stagger = STAGGER.base,
    batchMax = 8,
    interval,
    reverse = false,
    start = "top 85%",
  } = options;

  const axis = direction === "left" || direction === "right" ? "x" : "y";
  const sign = direction === "down" || direction === "right" ? -1 : 1;
  const offset = direction === "none" ? 0 : distance * sign;

  // Reduced motion: place the elements at their end state and create no
  // triggers at all. The content is present, nothing moves.
  if (isMotionSuppressed()) {
    gsap.set(elements, { opacity: 1, x: 0, y: 0, clearProps: "transform" });
    return [];
  }

  gsap.set(elements, { opacity: from, [axis]: offset });

  return ScrollTrigger.batch(elements, {
    start,
    batchMax,
    ...(interval !== undefined ? { interval } : {}),
    onEnter: (batch) =>
      gsap.to(batch, {
        opacity: 1,
        [axis]: 0,
        duration,
        ease,
        stagger,
        overwrite: true,
      }),
    ...(reverse
      ? {
          onLeaveBack: (batch: Element[]) =>
            gsap.to(batch, {
              opacity: from,
              [axis]: offset,
              duration: DURATION.fast,
              ease: EASING.soft,
              overwrite: true,
            }),
        }
      : {}),
  });
}
