/**
 * Reveal primitives — the workhorses of a premium site.
 *
 * All of these are *essential* motion: they carry content into view. Under
 * reduced motion the timings collapse to zero so the content still arrives.
 */
import type {
  MotionTarget,
  RevealOptions,
  TextRevealOptions,
} from "../types";

import { DISTANCE, DURATION, EASING, STAGGER } from "../core/config";
import { isBrowser } from "../core/env";
import { SplitText, ensureRegistered, gsap } from "../core/gsap";
import { resolveElements, resolveTarget } from "../core/target";
import {
  isMotionSuppressed,
  resolveTimings,
  toScrollTriggerVars,
} from "../core/vars";

/** Maps a direction onto the transform axis and sign it travels from. */
function offsetFor(
  direction: RevealOptions["direction"] = "up",
  distance: number,
): { axis: "x" | "y"; offset: number } {
  switch (direction) {
    case "down":
      return { axis: "y", offset: -distance };
    case "left":
      return { axis: "x", offset: distance };
    case "right":
      return { axis: "x", offset: -distance };
    case "none":
      return { axis: "y", offset: 0 };
    case "up":
    default:
      return { axis: "y", offset: distance };
  }
}

/**
 * Slides an element in while fading it up. The default reveal for any section.
 *
 * @example
 * ```ts
 * reveal(".stat", { direction: "up", stagger: STAGGER.base, scroll: true });
 * ```
 */
export function reveal(
  target: MotionTarget,
  options: RevealOptions = {},
): gsap.core.Tween | null {
  if (!isBrowser) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  const { axis, offset } = offsetFor(
    options.direction,
    options.distance ?? DISTANCE.md,
  );
  const { duration, delay, ease, stagger } = resolveTimings(options, {
    duration: DURATION.reveal,
    ease: EASING.premium,
    stagger: STAGGER.base,
  });

  return gsap.fromTo(
    resolved,
    { autoAlpha: options.from ?? 0, [axis]: offset },
    {
      autoAlpha: 1,
      [axis]: 0,
      duration,
      delay,
      ease,
      stagger,
      onStart: options.onStart,
      onComplete: options.onComplete,
      scrollTrigger: toScrollTriggerVars(options.scroll, {
        trigger: target,
        start: "top 85%",
      }),
    },
  );
}

/**
 * Reveals text by line, word, or character using SplitText.
 *
 * Splitting is deferred until fonts are ready — measuring line breaks against a
 * fallback font produces wrong lines that visibly re-flow on font swap.
 *
 * Returns a cleanup function that reverts both the animation and the DOM split.
 * Call it on unmount, or create this inside `useGSAPAnimation`, which does so
 * automatically.
 *
 * @example
 * ```ts
 * useGSAPAnimation(() => textReveal(headingRef, { split: "lines" }), { scope });
 * ```
 */
export function textReveal(
  target: MotionTarget,
  options: TextRevealOptions = {},
): () => void {
  if (!isBrowser) return () => {};
  ensureRegistered();

  const elements = resolveElements(target);
  if (elements.length === 0) return () => {};

  const {
    split = "lines",
    distance = 100,
    mask = true,
    scroll,
  } = options;

  const { duration, delay, ease, stagger } = resolveTimings(options, {
    duration: DURATION.reveal,
    ease: EASING.premium,
    stagger: split === "chars" ? STAGGER.tight : STAGGER.base,
  });

  let instance: SplitText | null = null;
  let cancelled = false;

  // SplitText needs words to compute sane line breaks; asking for lines alone
  // produces mid-word wrapping on narrow viewports.
  const type = split === "lines" ? "lines,words" : split;

  const build = () => {
    if (cancelled) return;

    instance = SplitText.create(elements, {
      type,
      ...(mask ? { mask: split } : {}),
      autoSplit: split === "lines",
      onSplit(self) {
        const units =
          split === "chars" ? self.chars : split === "words" ? self.words : self.lines;
        if (!units || units.length === 0) return;

        return gsap.from(units, {
          yPercent: isMotionSuppressed() ? 0 : distance,
          autoAlpha: 0,
          duration,
          delay,
          ease,
          stagger,
          onComplete: options.onComplete,
          scrollTrigger: toScrollTriggerVars(scroll, {
            trigger: target,
            start: "top 85%",
          }),
        });
      },
    });
  };

  // document.fonts is absent in some non-browser test environments.
  if (typeof document !== "undefined" && "fonts" in document) {
    void document.fonts.ready.then(build);
  } else {
    build();
  }

  return () => {
    cancelled = true;
    instance?.revert();
    instance = null;
  };
}

/**
 * Alias of {@link textReveal}, kept because "splitTextAnimation" is the name
 * most people search for.
 */
export const splitTextAnimation = textReveal;
