/**
 * Scale primitives.
 */
import type { MotionTarget, ScaleOptions } from "../types";

import { DURATION, EASING } from "../core/config";
import { isBrowser } from "../core/env";
import { ensureRegistered, gsap } from "../core/gsap";
import { resolveTarget } from "../core/target";
import { resolveTimings, toScrollTriggerVars } from "../core/vars";

/**
 * Settles an element from a larger scale down to rest, fading in as it lands.
 *
 * Used on imagery, this reads as the photograph "settling" into the layout —
 * the effect behind most luxury architecture and automotive sites.
 *
 * The element should sit inside a container with `overflow: hidden`, otherwise
 * the oversized start state spills past the intended frame.
 *
 * @example
 * ```ts
 * scaleImage(imageRef, { from: 1.15, scroll: true });
 * ```
 */
export function scaleImage(
  target: MotionTarget,
  options: ScaleOptions = {},
): gsap.core.Tween | null {
  if (!isBrowser) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  const { duration, delay, ease, stagger } = resolveTimings(options, {
    duration: DURATION.reveal,
    ease: EASING.premium,
  });

  return gsap.fromTo(
    resolved,
    { scale: options.from ?? 1.15, autoAlpha: 0 },
    {
      scale: options.to ?? 1,
      autoAlpha: 1,
      duration,
      delay,
      ease,
      stagger,
      // Scaling a raster image forces the compositor to resample it every
      // frame; a explicit hint keeps it on one texture for the tween.
      force3D: true,
      onStart: options.onStart,
      onComplete: options.onComplete,
      scrollTrigger: toScrollTriggerVars(options.scroll, {
        trigger: target,
        start: "top 85%",
      }),
    },
  );
}
