/**
 * Image-specific effects.
 *
 * Both of these assume the image sits inside a clipping frame:
 *
 * ```html
 * <div class="frame" style="overflow: hidden">
 *   <img class="photo" />
 * </div>
 * ```
 */
import type { ImageZoomOptions, MotionTarget, MotionOptions } from "../types";

import { DURATION, EASING } from "../core/config";
import { isBrowser } from "../core/env";
import { ensureRegistered, gsap } from "../core/gsap";
import { resolveTarget } from "../core/target";
import {
  resolveTimings,
  shouldSkipDecorativeMotion,
  toScrollTriggerVars,
} from "../core/vars";

/**
 * Scales an image continuously across its scroll range.
 *
 * Decorative — skipped entirely under reduced motion.
 *
 * @example
 * ```ts
 * imageZoom(".photo", { from: 1, to: 1.2 });
 * ```
 */
export function imageZoom(
  target: MotionTarget,
  options: ImageZoomOptions = {},
): gsap.core.Tween | null {
  if (!isBrowser) return null;
  if (shouldSkipDecorativeMotion()) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  return gsap.fromTo(
    resolved,
    { scale: options.from ?? 1 },
    {
      scale: options.to ?? 1.2,
      ease: EASING.none,
      force3D: true,
      scrollTrigger: toScrollTriggerVars(options.scroll ?? true, {
        trigger: target,
        start: "top bottom",
        end: "bottom top",
        scrub: true,
      }),
    },
  );
}

export interface ImageRevealOptions extends MotionOptions {
  /** Edge the clip opens from. Default `"bottom"`. */
  direction?: "top" | "bottom" | "left" | "right";
  /**
   * Counter-scale the image while the clip opens, so the photo appears to
   * settle rather than simply be uncovered. Default `1.15`.
   */
  scale?: number;
}

const CLIP_CLOSED: Record<string, string> = {
  bottom: "inset(100% 0% 0% 0%)",
  top: "inset(0% 0% 100% 0%)",
  left: "inset(0% 100% 0% 0%)",
  right: "inset(0% 0% 0% 100%)",
};

/**
 * Uncovers an image with a clip-path wipe while it settles from a larger scale.
 *
 * This is the signature editorial image entrance. `clip-path` is animated
 * rather than width/height because it never triggers layout.
 *
 * @example
 * ```ts
 * imageReveal(".photo", { direction: "bottom", scroll: true });
 * ```
 */
export function imageReveal(
  target: MotionTarget,
  options: ImageRevealOptions = {},
): gsap.core.Timeline | null {
  if (!isBrowser) return null;
  ensureRegistered();

  const resolved = resolveTarget(target);
  if (!resolved) return null;

  const { duration, delay, ease } = resolveTimings(options, {
    duration: DURATION.reveal,
    ease: EASING.dramatic,
  });
  const closed = CLIP_CLOSED[options.direction ?? "bottom"] ?? CLIP_CLOSED.bottom!;

  const timeline = gsap.timeline({
    delay,
    onStart: options.onStart,
    onComplete: options.onComplete,
    scrollTrigger: toScrollTriggerVars(options.scroll, {
      trigger: target,
      start: "top 85%",
    }),
  });

  timeline
    .fromTo(
      resolved,
      { clipPath: closed },
      { clipPath: "inset(0% 0% 0% 0%)", duration, ease },
    )
    .fromTo(
      resolved,
      { scale: options.scale ?? 1.15 },
      { scale: 1, duration, ease, force3D: true },
      // Start with the wipe so the two read as one gesture.
      "<",
    );

  return timeline;
}
