/**
 * Shared option resolution, and the engine's accessibility policy.
 *
 * Reduced motion is handled in exactly one place, and it draws a distinction
 * that matters:
 *
 * - **Essential** motion carries content into view. Under reduced motion the
 *   content must still arrive — it just arrives instantly instead of sliding.
 *   Skipping these outright would leave the page blank.
 * - **Decorative** motion (parallax, scroll-linked zoom) has no destination;
 *   it *is* the movement. Under reduced motion it is skipped entirely.
 */
import type { MotionOptions, ScrollOptions } from "../types";

import { getMotionConfig } from "./config";
import { isProduction, prefersReducedMotion } from "./env";
import { ScrollTrigger } from "./gsap";
import { resolveTarget } from "./target";

/** True when the engine should suppress motion for this visitor. */
export function isMotionSuppressed(): boolean {
  return getMotionConfig().respectReducedMotion && prefersReducedMotion();
}

/**
 * True when a purely decorative effect should not be created at all.
 * Essential animations use {@link resolveTimings} instead.
 */
export function shouldSkipDecorativeMotion(): boolean {
  return isMotionSuppressed();
}

export interface ResolvedTimings {
  duration: number;
  delay: number;
  ease: string;
  stagger: number;
}

/**
 * Merges caller options with engine defaults, collapsing everything to zero
 * when motion is suppressed so the animation lands on its end state at once.
 */
export function resolveTimings(
  options: MotionOptions = {},
  fallbacks: Partial<ResolvedTimings> = {},
): ResolvedTimings {
  const config = getMotionConfig();

  if (isMotionSuppressed()) {
    return { duration: 0, delay: 0, stagger: 0, ease: "none" };
  }

  return {
    duration: options.duration ?? fallbacks.duration ?? config.defaultDuration,
    delay: options.delay ?? fallbacks.delay ?? 0,
    ease: options.ease ?? fallbacks.ease ?? config.defaultEase,
    stagger: options.stagger ?? fallbacks.stagger ?? 0,
  };
}

/**
 * Translates engine {@link ScrollOptions} into ScrollTrigger vars.
 *
 * Returns `undefined` when no scroll binding was requested, which lets a
 * primitive spread the result into a tween unconditionally.
 */
export function toScrollTriggerVars(
  scroll: ScrollOptions | boolean | undefined,
  defaults: Partial<ScrollOptions> = {},
): ScrollTrigger.StaticVars | undefined {
  if (!scroll) return undefined;

  const options: ScrollOptions = scroll === true ? {} : scroll;
  const merged: ScrollOptions = { ...defaults, ...options };

  const vars: ScrollTrigger.StaticVars = {
    start: merged.start ?? "top 80%",
    end: merged.end ?? "bottom 20%",
  };

  const trigger = resolveTarget(merged.trigger);
  if (trigger) vars.trigger = trigger as ScrollTrigger.StaticVars["trigger"];

  // Under reduced motion, scrubbing is what produces the movement, so drop it
  // and let the animation play once on entry instead.
  if (merged.scrub !== undefined && !isMotionSuppressed()) {
    vars.scrub = merged.scrub;
  }

  if (merged.pin !== undefined && merged.pin !== false) {
    vars.pin =
      merged.pin === true
        ? true
        : (resolveTarget(merged.pin) as ScrollTrigger.StaticVars["pin"]);
  }
  if (merged.pinSpacing !== undefined) vars.pinSpacing = merged.pinSpacing;

  // scrub and toggleActions are mutually exclusive; scrub wins in GSAP, so only
  // forward toggleActions when nothing is scrubbing.
  if (merged.toggleActions !== undefined && vars.scrub === undefined) {
    vars.toggleActions = merged.toggleActions;
  }

  if (merged.once !== undefined) vars.once = merged.once;
  if (merged.refreshPriority !== undefined) {
    vars.refreshPriority = merged.refreshPriority;
  }
  if (merged.id !== undefined) vars.id = merged.id;

  // Markers are a development affordance and must never reach production, even
  // if a call site forgets to remove them.
  const wantsMarkers = merged.markers ?? getMotionConfig().markers;
  if (wantsMarkers && !isProduction) vars.markers = true;

  if (merged.onEnter) vars.onEnter = merged.onEnter;
  if (merged.onLeave) vars.onLeave = merged.onLeave;
  if (merged.onEnterBack) vars.onEnterBack = merged.onEnterBack;
  if (merged.onLeaveBack) vars.onLeaveBack = merged.onLeaveBack;
  if (merged.onUpdate) {
    const onUpdate = merged.onUpdate;
    vars.onUpdate = (self: ScrollTrigger) => {
      onUpdate(self.progress, self.direction as 1 | -1);
    };
  }

  return vars;
}
